# Code generated by Claude
"""
Table of grip_failure_weight_model results (David, Oct 26, steps 2e, 3, 4): one line per run, in the order given.

    python experiments/pad_runs_report.py <label>=<result.json> ...
"""
import json
import sys


def row(label, path):
    r = json.load(open(path))
    ph = r["grip"]["phases"]
    mom = r["pad"]["moments"]
    caps = r["sag_caps"]
    cp = r["down_last"]["Cp_m"] if r["down_last"] else 0.0               # the commanded pad pose minus the waypoint at the end of DOWN = the sag correction in force
    cr = r["down_last"]["Cr_rad"] if r["down_last"] else 0.0
    fp = r["first_plate_contact"]
    last = r["down_last"]
    out = [f"## {label}: total {1000 * r['true_total_kg']:.0f} g, {r['n_segments']} segments, grip cap {r['grip_force_cap_N_per_finger']:g} N/finger: {r['outcome']}"
           + (f" ({r['failure']})" if r.get("failure") else "") + f", on hotplate {r['beaker_on_hotplate']}, wall {r['wall_per_sim_s']:.3f} s per simulated s ({r['wall_s']:.0f} s for {r['sim_s']:.0f} s)"]
    for m in ("end_of_closing", "end_of_lift"):
        if m not in mom:
            continue
        c = mom[m]["contacts"]
        s = "; ".join(f"{f.split('_')[0]} {v['from_tip_mm_weighted']:.1f} from tip / {v['from_center_a_mm_weighted']:+.1f} from centre / {v['across_w_mm_weighted']:+.1f} across ({v['n_points']} pts, {v['total_N']:.1f} N, {','.join(g.replace('task_beaker_', '') for g in v['beaker_geoms'])})" for f, v in c.items())
        out.append(f"  contacts {m}: {s}")
    out.append("  tilt max / slide axial max / sideways max: " + "; ".join(f"{g} {ph[g]['max_tilt_deg']:.1f} deg / {ph[g]['max_slide_axial_mm']:.1f} / {ph[g]['max_slide_sideways_mm']:.1f} mm" for g in ("closing", "lift", "carry") if g in ph))
    out.append("  place: " + (f"first plate touch at t={fp['t']:.2f}, hand {fp['hand_err_norm_mm']:.1f} mm from the DOWN stop (z {fp['hand_err_mm'][2]:+.1f})" if fp else "beaker never touched the plate") + (f"; end of DOWN {last['err_norm_mm']:.2f} mm" if last else ""))
    out.append(f"  sag correction at the end of DOWN: {1000 * cp:.1f} mm (cap {1000 * caps['sag_max_m']:.0f}){' HIT' if cp >= 0.999 * caps['sag_max_m'] else ''}, {cr:.3f} rad (cap {caps['sag_max_rad']}){' HIT' if cr >= 0.999 * caps['sag_max_rad'] else ''}")
    for x in r["readings"]:
        out.append("  handoff " + x["label"] + ": " + ("no reading" if "failed" in x else f"{1000 * x['mass_kg']:.1f} g, unexplained {100 * x['unexplained']:.0f} %"))
    print("\n".join(out))


for a in sys.argv[1:]:
    l, p = a.split("=", 1)
    row(l, p)
